<!doctype html>
<html lang="pt"><head><meta charset="utf-8"><style>
@page{size:A4 portrait;margin:10mm 11mm 12mm}*{box-sizing:border-box}body{font-family:dejavusans,sans-serif;color:#16231f;font-size:8.5pt;margin:0}.header{background:#075f4d;color:#fff;padding:9mm 9mm 7mm;margin:-10mm -11mm 7mm}.brand{font-size:7pt;font-weight:bold;letter-spacing:1.8px;text-transform:uppercase;color:#bce9d7}.order{font-size:25pt;font-weight:bold;margin:2mm 0 1mm}.subtitle{font-size:9pt;color:#e1f5ed}.status{float:right;background:#d8f3e8;color:#075f4d;border-radius:10mm;padding:2mm 4mm;font-weight:bold}.meta{width:100%;border-collapse:separate;border-spacing:2.5mm 0;margin:0 -2.5mm 4mm}.meta td{width:25%;background:#edf7f3;border-left:2px solid #10a276;padding:2.6mm}.label{display:block;font-size:6.5pt;color:#63746d;text-transform:uppercase;letter-spacing:.4px;margin-bottom:.8mm}.value{font-size:10pt;font-weight:bold}.section{margin:4mm 0;page-break-inside:avoid}.section-title{font-size:10pt;color:#075f4d;text-transform:uppercase;letter-spacing:.6px;border-bottom:1.5px solid #0b896b;padding:0 0 1.5mm;margin:0 0 2mm}.section-no{display:inline-block;background:#075f4d;color:#fff;padding:1mm 2mm;margin-right:2mm}.product{width:100%;border-collapse:collapse}.product td{vertical-align:top}.art{width:48%;height:72mm;background:#f1f5f3;border:1px solid #d9e5e0;text-align:center;padding:3mm}.art img{max-width:100%;max-height:65mm}.empty{color:#74827d;padding-top:28mm}.spec{padding-left:5mm}.spec-row{border-bottom:1px solid #e0e8e4;padding:1.5mm 0}.features{width:100%;border-collapse:separate;border-spacing:1.5mm}.features td{background:#f2f6f4;padding:2mm;text-align:center;font-size:7pt}.features strong{display:block;font-size:9pt;color:#075f4d}.grid{width:100%;border-collapse:collapse}.grid th{background:#075f4d;color:#fff;font-size:7pt;text-transform:uppercase;text-align:left;padding:2mm}.grid td{border-bottom:1px solid #dce6e1;padding:2mm;vertical-align:top}.grid tr:nth-child(even) td{background:#f6f9f8}.cards{width:100%;border-collapse:separate;border-spacing:2mm}.cards td{width:25%;background:#edf7f3;border-top:2px solid #0b896b;padding:3mm}.cards strong{font-size:15pt;color:#075f4d}.note{background:#fff8df;border-left:3px solid #e7af27;padding:3mm}.page-break{page-break-before:always}.footer{position:fixed;bottom:-7mm;left:0;right:0;border-top:1px solid #d5dfdb;padding-top:2mm;color:#718079;font-size:7pt}.footer-right{float:right}.muted{color:#718079}.total td{font-weight:bold;background:#e5f3ed!important}.signature{width:100%;margin-top:10mm}.signature td{width:33%;padding:9mm 5mm 0;border-top:1px solid #83908b;text-align:center;color:#63746d}
</style></head><body>
<div class="footer"><span>Dossier de Produção · OF <?=h($o['order_number'])?></span><span class="footer-right">Gerado em <?=date('d/m/Y H:i')?> · GesTisser</span></div>
<header class="header"><span class="status"><?=h($o['status'])?></span><div class="brand">Centro operacional · Dossier de produção</div><div class="order">OF <?=h($o['order_number'])?></div><div class="subtitle"><?=h($o['customer_name']?:'Cliente não definido')?> &nbsp;·&nbsp; <?=h($o['article_code']?:'Artigo não definido')?> &nbsp;·&nbsp; <?=h($o['article_description']??'')?></div></header>
<table class="meta"><tr><td><span class="label">Quantidade planeada</span><span class="value"><?=pd_num($o['planned_quantity'])?></span></td><td><span class="label">Data de entrega</span><span class="value"><?=h($o['due_date']?:'—')?></span></td><td><span class="label">Ficha técnica</span><span class="value">v<?=h($o['technical_version']??$s['_technical_sheet_version']??'—')?></span></td><td><span class="label">Encomenda cliente</span><span class="value"><?=h($o['customer_order_reference']??$s['_order']['customer_order']??'—')?></span></td></tr></table>
<section class="section"><h2 class="section-title"><span class="section-no">01</span>Artigo e especificações</h2><table class="product"><tr><td class="art"><?php if($mainDocumentThumbnail!==''):?><img src="<?=h($mainDocumentThumbnail)?>" alt="Maqueta do artigo"><?php else:?><div class="empty"><strong>MAQUETA DO ARTIGO</strong><br><?=h($mainDocument['title']??'Sem imagem principal associada')?></div><?php endif;?></td><td class="spec"><?php foreach(['customer_product_code'=>'Referência cliente','description'=>'Descrição','material'=>'Material','composition'=>'Composição','width'=>'Largura','length'=>'Comprimento','grammage'=>'Gramagem','theoretical_weight'=>'Peso teórico','seam_type'=>'Costura','thread_color'=>'Cor do fio'] as$key=>$label):$value=trim((string)($s[$key]??''));if($value==='')continue;?><div class="spec-row"><span class="label"><?=h($label)?></span><strong><?=h($value)?></strong></div><?php endforeach;?></td></tr></table></section>
<section class="section"><h2 class="section-title"><span class="section-no">02</span>Características e embalagem</h2><table class="features"><tr><?php foreach(['microperforation'=>'Microperfuração','has_gusset'=>'Fole','centered_gusset'=>'Fole centrado','has_handle'=>'Asa','has_holes'=>'Furo'] as$key=>$label):?><td><strong><?=!empty($s[$key])?'SIM':'NÃO'?></strong><?=h($label)?></td><?php endforeach;?></tr></table><table class="grid"><tr><th>Medida do fole</th><th>Perfuração</th><th>Palete</th><th>Tampa</th><th>Filme</th><th>Cintas</th></tr><tr><?php foreach(['gusset_length','perforation_type','pallet_dimensions','pallet_lid','pallet_film','pallet_straps'] as$key):?><td><?=h(trim((string)($s[$key]??''))?:'—')?></td><?php endforeach;?></tr></table></section>
<section class="section"><h2 class="section-title"><span class="section-no">03</span>Routing e operações</h2><table class="grid"><tr><th>Seq.</th><th>Operação / instrução</th><th>Máquina</th><th>Previsto</th><th>Real</th><th>Qtd. boa</th><th>Estado</th></tr><?php foreach($d['operations'] as$op):?><tr><td><?=h($op['sequence_no'])?></td><td><strong><?=h($op['name'])?></strong><?php if(trim((string)($op['instructions']??''))!==''):?><br><span class="muted"><?=h($op['instructions'])?></span><?php endif;?></td><td><?=h($op['machine_name']?:'—')?></td><td><?=pd_time($op['planned_minutes'])?></td><td><?=pd_time($op['actual_minutes'])?></td><td><?=pd_num($op['quantity_good'])?></td><td><?=h($op['status'])?></td></tr><?php endforeach;?><?php if(!$d['operations']):?><tr><td colspan="7" class="muted">Esta OF ainda não tem operações no routing.</td></tr><?php endif;?></table></section>
<div class="page-break"></div>
<header class="header"><span class="status"><?=h($o['status'])?></span><div class="brand">Relatório operacional</div><div class="order">OF <?=h($o['order_number'])?></div><div class="subtitle">Produção, consumos, desvios e validação</div></header>
<section class="section"><h2 class="section-title"><span class="section-no">04</span>Resumo de produção</h2><table class="cards"><tr><?php foreach([['Quantidade boa',pd_num($m['good'])],['Desperdício',pd_num($m['rejected']).' / '.pd_num($m['waste_percent'],1).' %'],['Eficiência',pd_num($m['efficiency'],1).' %'],['Tempo real',pd_time($m['actual_minutes'])]] as$card):?><td><span class="label"><?=h($card[0])?></span><strong><?=h($card[1])?></strong></td><?php endforeach;?></tr></table></section>
<section class="section"><h2 class="section-title"><span class="section-no">05</span>Consumos previstos e reais</h2><table class="grid"><tr><th>Artigo</th><th>Descrição</th><th>Lote</th><th>Previsto</th><th>Real</th><th>Diferença</th><th>Custo</th></tr><?php foreach($d['consumptions'] as$c):?><tr><td><?=h($c['code'])?></td><td><?=h($c['description'])?></td><td><?=h($c['lot']?:'—')?></td><td><?=pd_num($c['planned_quantity'],3)?> <?=h($c['unit_code'])?></td><td><?=pd_num($c['quantity'],3)?></td><td><?=pd_num((float)$c['quantity']-(float)$c['planned_quantity'],3)?></td><td><?=pd_money((float)$c['quantity']*(float)$c['unit_cost'])?></td></tr><?php endforeach;?><?php if(!$d['consumptions']):?><tr><td colspan="7" class="muted">Sem consumos reais registados.</td></tr><?php endif;?></table></section>
<section class="section"><h2 class="section-title"><span class="section-no">06</span>Custos · previsto vs. realizado</h2><table class="grid"><tr><th>Categoria</th><th>Previsto</th><th>Real</th><th>Desvio</th></tr><?php foreach($d['costs']['rows'] as$r):?><tr><td><?=h($r['category'])?></td><td><?=pd_money($r['planned'])?></td><td><?=pd_money($r['actual'])?></td><td><?=($r['difference']>0?'+':'').pd_money($r['difference'])?></td></tr><?php endforeach;?><tr class="total"><td>Total</td><td><?=pd_money($m['planned_cost'])?></td><td><?=pd_money($m['actual_cost'])?></td><td><?=pd_money($m['actual_cost']-$m['planned_cost'])?></td></tr></table></section>
<section class="section"><h2 class="section-title"><span class="section-no">07</span>Observações e validação</h2><div class="note"><?=nl2br(h(trim((string)($o['notes']??''))?:'Sem observações registadas.'))?></div><table class="signature"><tr><td>Produção</td><td>Qualidade</td><td>Responsável</td></tr></table></section>
</body></html>
